import * as THREE from 'three/webgpu';
import { color, uniform, texture, mix, uv, vec3, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pedestal-material-study';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  const disposables = [];

  // Backdrop
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  const gradUv = uv();
  const stop0 = color('#0b0b10');
  const stop1 = color('#101017');
  const stop2 = color('#16161d');
  const t = gradUv.y;
  const lower = mix(stop0, stop1, t.div(0.7).clamp(0, 1));
  const upper = mix(stop1, stop2, t.sub(0.7).div(0.3).clamp(0, 1));
  backdropMat.colorNode = mix(lower, upper, t.smoothstep(0.65, 0.75));
  const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdrop.geometry, backdropMat);

  // Pedestal
  const pedestalMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestalGeo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64, 1, false);
  const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  // Chamfer edge ring (simple torus for catching light)
  const chamferMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#1a1a20'),
    roughness: 0.5,
    metalness: 0.4,
  });
  const chamferGeo = new THREE.TorusGeometry(1.1, 0.03, 8, 64);
  const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  group.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // Contact shadow
  const shadowMat = new THREE.MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowUv = uv();
  const dist = shadowUv.sub(0.5).length().mul(2.0);
  const shadowAlpha = float(0.6).mul(float(1.0).sub(dist.smoothstep(0.6, 1.0)));
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = shadowAlpha;
  const shadowGeo = new THREE.CircleGeometry(1.5, 48);
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // Torus knot material study
  const roughnessMap = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  roughnessMap.wrapS = roughnessMap.wrapT = THREE.RepeatWrapping;

  const knotMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#c8ccd2'),
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });

  const mapNode = texture(roughnessMap, uv());
  const centerRough = float(0.9);
  const jitter = uv().x.mul(37.13).sin().mul(uv().y.mul(19.7).cos()).mul(0.02);
  knotMat.roughnessNode = float(0.55).mul(mapNode.r.mul(centerRough).clamp(0, 1)).add(jitter).clamp(0.05, 1.0);

  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  const knotGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knot = new THREE.Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);
  disposables.push(knotGeo, knotMat);

  // Lights - neutral studio IBL substitute + key light
  const hemi = new THREE.HemisphereLight(0xf0f0f5, 0x14141a, 0.7);
  group.add(hemi);
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);
  const fillLight = new THREE.PointLight(0xffffff, 0.4);
  fillLight.position.set(-2, 1, 2);
  group.add(fillLight);

  // Text content
  const headline = createTextMesh(ctx.fontAtlas, {
    text: 'Material study 03',
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(0, -1.2, 0);
  group.add(headline);

  const caption = createTextMesh(ctx.fontAtlas, {
    text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
  });
  caption.position.set(0, -1.6, 0);
  group.add(caption);

  // Apply cinematic primitives
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (fn) {
        const handle = fn(knot, primitive.params);
        primitiveHandles.push(handle);
      }
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill && tl.kill());
    primitiveHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    roughnessMap.dispose();
    if (headline.userData && headline.userData.dispose) headline.userData.dispose();
    if (caption.userData && caption.userData.dispose) caption.userData.dispose();
    hemi.dispose && hemi.dispose();
    keyLight.dispose && keyLight.dispose();
    fillLight.dispose && fillLight.dispose();
  };

  return group;
}
